package de.corporate.lc.user.api;
import de.corporate.lc.audit.service.AuditService; import de.corporate.lc.user.service.UserService; import jakarta.validation.Valid; import org.springframework.http.ResponseEntity; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/users") public class UserController {private final UserService service;private final AuditService audit;public UserController(UserService s,AuditService a){service=s;audit=a;}@GetMapping public List<UserView> all(){return service.all();}@GetMapping("/assignable")public List<AssignableUser> assignable(){return service.assignable();}@PostMapping public UserView create(@Valid @RequestBody UserRequest r,Authentication a){UserView u=service.create(r);audit.record(a,"USER_CREATED","USER",u.id(),u.username()+" · "+u.role());return u;}@PutMapping("/{id}")public UserView update(@PathVariable UUID id,@Valid @RequestBody UserRequest r,Authentication a){UserView u=service.update(id,r,a.getName());audit.record(a,"USER_UPDATED","USER",id,u.username()+" · "+u.role()+" · "+(u.active()?"aktiv":"gesperrt"));return u;}@DeleteMapping("/{id}")public ResponseEntity<Void> delete(@PathVariable UUID id,Authentication a){service.delete(id,a.getName());audit.record(a,"USER_DELETED","USER",id,"Benutzer gelöscht");return ResponseEntity.noContent().build();}}
